import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;

/** A discount rate typed by an admin, held as whole basis points (12.5% is 1250). */
final class DiscountPercent {

    static final String INVALID = "INVALID_DISCOUNT";

    private static final long MAX_BASIS_POINTS = 10_000L;

    private DiscountPercent() {
    }

    /**
     * Parses text such as "12.5" or "0.25" into basis points, accepting 0 to 100 with at most two decimals.
     */
    static long toBasisPoints(String text) {
        if (null == text) {
            throw invalid(text);
        }
        String s = text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);
        if (whole.isEmpty() || whole.length() > 3 || !allDigits(whole)) {
            throw invalid(text);
        }
        if (dot >= 0 && (fraction.isEmpty() || fraction.length() > 2 || !allDigits(fraction))) {
            throw invalid(text);
        }
        long basisPoints = Long.parseLong(whole) * 100L;
        if (fraction.length() == 1) {
            basisPoints += Long.parseLong(fraction) * 10L;
        } else if (fraction.length() == 2) {
            basisPoints += Long.parseLong(fraction);
        }
        if (basisPoints > MAX_BASIS_POINTS) {
            throw invalid(text);
        }
        return basisPoints;
    }

    /** The discount on a non-negative total, rounded half up to a whole minor unit. */
    static Money discountOf(Money total, long basisPoints) {
        if (total.minorUnits() < 0) {
            throw new IllegalStateException("Negative total: " + total.minorUnits());
        }
        long product = Math.multiplyExact(total.minorUnits(), basisPoints);
        long discount = Math.addExact(product, MAX_BASIS_POINTS / 2) / MAX_BASIS_POINTS;
        return new Money(discount, total.currency());
    }

    private static boolean allDigits(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static ShopProblem invalid(String text) {
        return new ShopProblem(INVALID, "Discount must be a percentage from 0 to 100 with at most two decimals: " + text);
    }
}
}

