import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import org.junit.jupiter.api.Test;

class DiscountPercentTest {

    @Test
    void parsesPercentToBasisPoints() {
        assertEquals(1250, DiscountPercent.toBasisPoints("12.5"));
        assertEquals(1200, DiscountPercent.toBasisPoints("12"));
        assertEquals(25, DiscountPercent.toBasisPoints("0.25"));
        assertEquals(50, DiscountPercent.toBasisPoints(" 0.5 "));
        assertEquals(10_000, DiscountPercent.toBasisPoints("100"));
        assertEquals(0, DiscountPercent.toBasisPoints("0"));
    }

    @Test
    void rejectsMalformedOrOutOfRangeText() {
        for (String bad : new String[] {null, "", " ", "abc", "-1", "+5", "12,5", "12.", ".5", "1e2", "12.345", "100.01", "101", "1000"}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> DiscountPercent.toBasisPoints(bad), String.valueOf(bad));
            assertEquals(DiscountPercent.INVALID, problem.code());
        }
    }

    @Test
    void discountRoundsHalfUp() {
        assertEquals(Money.pln(1), DiscountPercent.discountOf(Money.pln(100), 50));   // 0.5% of 1.00 PLN
        assertEquals(Money.pln(2), DiscountPercent.discountOf(Money.pln(300), 75));   // 2.25 -> 2
        assertEquals(Money.pln(3), DiscountPercent.discountOf(Money.pln(250), 125));  // 3.125 -> 3
        assertEquals(Money.pln(5), DiscountPercent.discountOf(Money.pln(1000), 50));  // 5.00 exactly
        assertEquals(Money.pln(0), DiscountPercent.discountOf(Money.pln(99), 50));    // 0.495 -> 0
        assertEquals(Money.pln(1), DiscountPercent.discountOf(Money.pln(100), 100));  // 0.005 -> 0.01? no: see below
    }
}
}

